/* harmony default export */ __webpack_exports__["default"] = ("<section class=\"control-bar\">\r\n  <h1>Elements alignment</h1>\r\n</section>\r\n\r\n<section class=\"content-container\">\r\n  <aa-button\r\n    *ngIf=\"showMarkers\"\r\n    (buttonClick)=\"showMarkers =! showMarkers\"\r\n    [buttonClass]=\"'custom-icons light-blue'\"\r\n    [buttonId]=\"'buttonIdC'\"\r\n    [buttonText]=\"'Hide guides'\"\r\n    [customIcons]=\"true\"\r\n    [buttonIcon]=\"'menu'\"\r\n    [fieldClass]=\"'boxed margin-bottom-1'\"\r\n  ></aa-button>\r\n  <aa-button\r\n    *ngIf=\"!showMarkers\"\r\n    (buttonClick)=\"showMarkers =! showMarkers\"\r\n    [buttonClass]=\"'custom-icons light-blue'\"\r\n    [buttonId]=\"'buttonIdC'\"\r\n    [buttonText]=\"'Show guides'\"\r\n    [customIcons]=\"true\"\r\n    [buttonIcon]=\"'menu'\"\r\n    [fieldClass]=\"'boxed margin-bottom-1'\"\r\n  ></aa-button>\r\n\r\n  <h2 class=\"margin-bottom-0\">Form elements</h2>\r\n  <div class=\"flex-group flex-start position-relative\">\r\n    <section class=\"alignment-marker\" *ngIf=\"showMarkers\">\r\n      <div>\r\n        <div><!-- marker --></div>\r\n      </div>\r\n    </section>\r\n    <aa-input-text\r\n      [fieldClass]=\"'small'\"\r\n      [isOptional]=\"true\"\r\n      [inputTextLabel]=\"'Input text optional'\"\r\n    ></aa-input-text>\r\n    <div class=\"field\">\r\n      <label>Native select</label\r\n      ><select>\r\n      <option>Please select</option>\r\n      <option>Cats</option>\r\n      <option>Dogs</option>\r\n      <option>Rabbits</option>\r\n    </select>\r\n    </div>\r\n\r\n    <fieldset>\r\n      <legend>Radio</legend>\r\n      <div class=\"field radio\">\r\n        <label [ngClass]=\"{ checked: myRadios === 'yes' }\">\r\n          <input\r\n            [(ngModel)]=\"myRadios\"\r\n            name=\"myRadios\"\r\n            type=\"radio\"\r\n            value=\"yes\"\r\n          />\r\n          <span>Yes</span>\r\n        </label>\r\n      </div>\r\n      <div class=\"field radio\">\r\n        <label [ngClass]=\"{ checked: myRadios === 'no' }\">\r\n          <input\r\n            [(ngModel)]=\"myRadios\"\r\n            name=\"myRadios\"\r\n            type=\"radio\"\r\n            value=\"no\"\r\n          />\r\n          <span>No</span>\r\n        </label>\r\n      </div>\r\n    </fieldset>\r\n\r\n    <fieldset>\r\n      <legend>Checkbox</legend>\r\n      <div class=\"field checkbox\">\r\n        <label for=\"id-01\">\r\n          <input type=\"checkbox\" value=\"Chickens\" name=\"id-01\" id=\"id-01\"/>\r\n          <span>Chickens</span>\r\n        </label>\r\n      </div>\r\n    </fieldset>\r\n\r\n    <aa-button\r\n      [buttonClass]=\"'primary settings'\"\r\n      [buttonLabel]=\"'Settings'\"\r\n      [buttonText]=\"'Settings'\"\r\n    ></aa-button>\r\n    <aa-button\r\n      [buttonClass]=\"'primary filter'\"\r\n      [buttonLabel]=\"'Filter'\"\r\n      [buttonText]=\"'Filter'\"\r\n    ></aa-button>\r\n    <aa-button\r\n      [buttonClass]=\"'primary'\"\r\n      [buttonLabel]=\"'Primary'\"\r\n      [buttonText]=\"'Primary'\"\r\n    ></aa-button>\r\n    <aa-button\r\n      [buttonClass]=\"'reject'\"\r\n      [buttonLabel]=\"'Reject'\"\r\n      [buttonText]=\"'Reject'\"\r\n    ></aa-button>\r\n    <aa-button\r\n      [buttonClass]=\"'review blue'\"\r\n      [buttonLabel]=\"'Review'\"\r\n      [buttonText]=\"'Review'\"\r\n    ></aa-button>\r\n    <aa-button\r\n      [buttonClass]=\"'primary calendar'\"\r\n      [buttonLabel]=\"'Calendar'\"\r\n      [buttonText]=\"'Calendar'\"\r\n    ></aa-button>\r\n    <aa-file-upload \r\n      fileUploadLabel=\"File upload\" \r\n      fileUploadId=\"fileUploadId\" \r\n      fileUploadExtentions=\".csv,.xlsx,.xls,.pdf\"\r\n      fileUploadText=\"Choose file...\"\r\n      fieldClass=\"\">\r\n    </aa-file-upload>\r\n  </div>\r\n\r\n  <h2 class=\"margin-bottom-0\">Ng-Select variations</h2>\r\n  <div class=\"flex-group flex-start position-relative\">\r\n    <section class=\"alignment-marker\" *ngIf=\"showMarkers\">\r\n      <div>\r\n        <div><!-- marker --></div>\r\n      </div>\r\n    </section>\r\n    \r\n    <div class=\"field\">\r\n      <label>Ng select</label>\r\n      <ng-select \r\n        [items]=\"cities\"\r\n        bindLabel=\"name\"\r\n        placeholder=\"Select city\"\r\n        [(ngModel)]=\"selectedCity\"\r\n      >\r\n      </ng-select>\r\n    </div>\r\n    <div class=\"field\">\r\n      <label>Ng select - Multiselect</label>\r\n      <ng-select \r\n        [items]=\"cities2\"\r\n        bindLabel=\"name\"\r\n        bindValue=\"id\"\r\n        [multiple]=\"true\"\r\n        placeholder=\"Select cities\"\r\n        [(ngModel)]=\"selectedCityIds\"\r\n      >\r\n    </ng-select>\r\n    </div>\r\n    <div class=\"field\">\r\n      <label>Ng select - Custom tags</label>\r\n      <ng-select \r\n        [items]=\"users\"\r\n        bindLabel=\"name\"\r\n        bindValue=\"id\"\r\n        [addTag]=\"addCustomUser\"\r\n        [multiple]=\"true\"\r\n        placeholder=\"Add tag\"\r\n        [(ngModel)]=\"selectedUserIds\"\r\n        >\r\n    </ng-select>\r\n    </div>\r\n    <div class=\"field\">\r\n      <label>Ng select - High performance. Handles over 10,000 items</label>\r\n      <ng-select \r\n        [items]=\"cities4\"\r\n        [virtualScroll]=\"true\"\r\n        bindLabel=\"name\"\r\n        bindValue=\"id\"\r\n        placeholder=\"Select city\"\r\n        [(ngModel)]=\"selectedCityId\"\r\n      >\r\n      </ng-select>\r\n    </div>\r\n    <div class=\"field\">\r\n      <label>Ng select - Grouping sections</label>\r\n      <ng-select \r\n        [items]=\"accounts\"\r\n        bindLabel=\"name\"\r\n        bindValue=\"name\"\r\n        groupBy=\"country\"\r\n        [(ngModel)]=\"selectedAccount\"\r\n      >\r\n      </ng-select>\r\n    </div>\r\n  </div>\r\n\r\n  <h2>Alert shields</h2>\r\n  <div class=\"flex-group flex-start position-relative\">\r\n    <section class=\"alignment-marker shields\" *ngIf=\"showMarkers\">\r\n      <div>\r\n        <div></div>\r\n      </div>\r\n    </section>\r\n    <div>\r\n      <div class=\"alert-shield success\">Success</div>\r\n    </div>\r\n    <div>\r\n      <div class=\"alert-shield green\">Success</div>\r\n    </div>\r\n    <div>\r\n      <div class=\"alert-shield pending\">Pending</div>\r\n    </div>\r\n    <div>\r\n      <div class=\"alert-shield risk-high\">Risk high</div>\r\n    </div>\r\n    <div>\r\n      <div class=\"alert-shield risk-low-approved\">Risk low approved</div>\r\n    </div>\r\n    <div>\r\n      <div class=\"alert-shield removed\">Removed</div>\r\n    </div>\r\n    <div>\r\n      <div class=\"alert-shield import\">Import from AD</div>\r\n    </div>\r\n  </div>\r\n\r\n  <h2>Alert shields small</h2>\r\n  <div class=\"flex-group flex-start position-relative\">\r\n    <section class=\"alignment-marker shields small\" *ngIf=\"showMarkers\">\r\n      <div>\r\n        <div></div>\r\n      </div>\r\n    </section>\r\n    <div>\r\n      <div class=\"alert-shield small success\">Success</div>\r\n    </div>\r\n    <div>\r\n      <div class=\"alert-shield small green\">Success</div>\r\n    </div>\r\n    <div>\r\n      <div class=\"alert-shield small red\">Success</div>\r\n    </div>\r\n    <div>\r\n      <div class=\"alert-shield small orange\">Success</div>\r\n    </div>\r\n    <div>\r\n      <div class=\"alert-shield small pending\">Pending</div>\r\n    </div>\r\n    <div>\r\n      <div class=\"alert-shield small risk-high\">Risk high</div>\r\n    </div>\r\n    <div>\r\n      <div class=\"alert-shield small removed\">Removed</div>\r\n    </div>\r\n    <div>\r\n      <div class=\"alert-shield small import\">Import from AD</div>\r\n    </div>\r\n  </div>\r\n\r\n  <h2>Alerts</h2>\r\n  <div class=\"flex-group flex-start position-relative\">\r\n    <section class=\"alignment-marker shields\" *ngIf=\"showMarkers\">\r\n      <div>\r\n        <div></div>\r\n      </div>\r\n    </section>\r\n    <div>\r\n      <aa-alert [alertClass]=\"'success'\" [alertText]=\"'Success'\"></aa-alert>\r\n    </div>\r\n    <div>\r\n      <aa-alert [alertClass]=\"'warning'\" [alertText]=\"'Success'\"></aa-alert>\r\n    </div>\r\n    <div>\r\n      <aa-alert [alertClass]=\"'error'\" [alertText]=\"'Success'\"></aa-alert>\r\n    </div>\r\n  </div>\r\n\r\n  <h2>Alerts double line</h2>\r\n  <div class=\"flex-group flex-start position-relative\">\r\n    <section class=\"alignment-marker shields-double\" *ngIf=\"showMarkers\">\r\n      <div>\r\n        <div></div>\r\n      </div>\r\n    </section>\r\n    <div>\r\n      <aa-alert\r\n        [alertClass]=\"'success'\"\r\n        [alertText]=\"\r\n          'As a result you are already too old for fairy tales, and by the time it is printed and bound you will be older still.'\r\n        \"\r\n      ></aa-alert>\r\n    </div>\r\n    <div>\r\n      <aa-alert\r\n        [alertClass]=\"'error'\"\r\n        [alertText]=\"\r\n          'As a result you are already too old for fairy tales, and by the time it is printed and bound you will be older still.'\r\n        \"\r\n      ></aa-alert>\r\n    </div>\r\n  </div>\r\n  \r\n  <h1 class=\"margin-top-2\">Checkbox and radio layout variations</h1>\r\n  <div class=\"describe\">\r\n    By default, our fieldset radios and checkboxes appear horizontally. If \r\n    you need a side-by-side layout similar to the below example, add the class\r\n    .flex-group and .flex-column to the fieldset which in this example appears on the left-side.\r\n  </div>\r\n  \r\n  <div>\r\n    <div role=\"alert\" class=\"margin-bottom-0 info\"><strong>Default</strong> - no .flex-group.flex-column on left-side fieldset</div>\r\n  </div>\r\n  \r\n  <div class=\"flex-group flex-start\">\r\n    <fieldset>\r\n      <legend>Radio button</legend>\r\n      <div class=\"field radio\">\r\n        <label [ngClass]=\"{checked: myRadios==='yes'}\">\r\n          <input [(ngModel)]=\"myRadios\" name=\"myRadios\" type=\"radio\" value=\"yes\">\r\n          <span>Yes</span>\r\n        </label>\r\n      </div>\r\n      <div class=\"field radio\">\r\n        <label [ngClass]=\"{checked: myRadios==='no'}\">\r\n          <input [(ngModel)]=\"myRadios\" name=\"myRadios\" type=\"radio\" value=\"no\">\r\n          <span>No</span>\r\n        </label>\r\n      </div>\r\n    </fieldset>\r\n\r\n    <div class=\"flex-group\">\r\n      <div class=\"field\">\r\n        <label for=\"pet-select\">Select - choose a pet</label>\r\n        <select name=\"pets\" id=\"pet-select\">\r\n          <option value=\"\" selected>Please select</option>\r\n          <option value=\"dog\">Dog</option>\r\n          <option value=\"cat\">Cat</option>\r\n          <option value=\"hamster\">Hamster</option>\r\n          <option value=\"parrot\">Parrot</option>\r\n          <option value=\"spider\">Spider</option>\r\n          <option value=\"goldfish\">Goldfish</option>\r\n        </select>\r\n      </div>\r\n      <div class=\"field\">\r\n        <label for=\"pet-select\">Select - choose a pet</label>\r\n        <select name=\"pets\" id=\"pet-select\">\r\n          <option value=\"\" selected>Please select</option>\r\n          <option value=\"dog\">Dog</option>\r\n          <option value=\"cat\">Cat</option>\r\n          <option value=\"hamster\">Hamster</option>\r\n          <option value=\"parrot\">Parrot</option>\r\n          <option value=\"spider\">Spider</option>\r\n          <option value=\"goldfish\">Goldfish</option>\r\n        </select>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div>\r\n    <div role=\"alert\" class=\"margin-top-2 margin-bottom-0 info\">\r\n      <strong>Custom</strong> - Add .flex-group.flex-column on left-side fieldset.\r\n      <br/><strong class=\"aa-red-100\">To override the extra margins added for flex-column layout, add additional \r\n        class .margin-bottom-0-5 to div.field.radio</strong>\r\n    </div>\r\n  </div>  \r\n  <div class=\"flex-group\">\r\n    <div class=\"flex-group flex-start\">\r\n      <fieldset class=\"flex-group flex-column\">\r\n        <legend>Radio button</legend>\r\n        <div class=\"field radio\">\r\n          <label [ngClass]=\"{checked: myRadios==='yes'}\">\r\n            <input [(ngModel)]=\"myRadios\" name=\"myRadios\" type=\"radio\" value=\"yes\">\r\n            <span>Yes</span>\r\n          </label>\r\n        </div>\r\n        <div class=\"field radio\">\r\n          <label [ngClass]=\"{checked: myRadios==='no'}\">\r\n            <input [(ngModel)]=\"myRadios\" name=\"myRadios\" type=\"radio\" value=\"no\">\r\n            <span>No</span>\r\n          </label>\r\n        </div>\r\n      </fieldset>\r\n  \r\n      <div>\r\n        <div class=\"field\">\r\n          <label for=\"pet-select\">Select - choose a pet</label>\r\n          <select name=\"pets\" id=\"pet-select\">\r\n            <option value=\"\" selected>Please select</option>\r\n            <option value=\"dog\">Dog</option>\r\n            <option value=\"cat\">Cat</option>\r\n            <option value=\"hamster\">Hamster</option>\r\n            <option value=\"parrot\">Parrot</option>\r\n            <option value=\"spider\">Spider</option>\r\n            <option value=\"goldfish\">Goldfish</option>\r\n          </select>\r\n        </div>\r\n        <div class=\"field\">\r\n          <label for=\"pet-select\">Select - choose a pet</label>\r\n          <select name=\"pets\" id=\"pet-select\">\r\n            <option value=\"\" selected>Please select</option>\r\n            <option value=\"dog\">Dog</option>\r\n            <option value=\"cat\">Cat</option>\r\n            <option value=\"hamster\">Hamster</option>\r\n            <option value=\"parrot\">Parrot</option>\r\n            <option value=\"spider\">Spider</option>\r\n            <option value=\"goldfish\">Goldfish</option>\r\n          </select>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n");

